      level: {
        description:
          '动作等级（DESIGN §9.1）：提议时按目录等级与目标状态确定。pod_restart 满足可重建条件时为 reversible_recreatable，否则为 irreversible。',
        $ref: '#/$defs/level',
      },
      tier: { description: '风险档位（DESIGN §9.2）。', $ref: '#/$defs/tier' },
