      canon_version: {
        description:
          '规范化版本：jcs-sha256-v1 表示 RFC 8785 JCS、UTF-8 编码、SHA-256、小写十六进制并带 "sha256:" 前缀。',
        type: 'string',
        enum: ['jcs-sha256-v1'],
      },
